import{_ as a,o,c as t,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Σελίδες, ενότητες και πλοήγηση","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/pages-and-sections.md","filePath":"el/websites/pages-and-sections.md"}'),i={name:"el/websites/pages-and-sections.md"};function l(r,e,c,d,n,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="σελιδες-ενοτητες-και-πλοηγηση" tabindex="-1">Σελίδες, ενότητες και πλοήγηση <a class="header-anchor" href="#σελιδες-ενοτητες-και-πλοηγηση" aria-label="Permalink to &quot;Σελίδες, ενότητες και πλοήγηση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Δημιουργήστε τη δομή σελίδων και τις επαναχρησιμοποιήσιμες ενότητες μιας ιστοσελίδας. Εργαστείτε σε εξουσιοδοτημένο προσχέδιο με έγκυρο σύστημα σχεδιασμού.</p><h2 id="οργανωση-σελιδων" tabindex="-1">Οργάνωση σελίδων <a class="header-anchor" href="#οργανωση-σελιδων" aria-label="Permalink to &quot;Οργάνωση σελίδων&quot;">​</a></h2><ol><li>Επιλέξτε ιστοσελίδα στο πάνελ δομής.</li><li>Προσθέστε, αντιγράψτε ή αναδιατάξτε σελίδες. Η αρχική διαδρομή <code>/</code> προστατεύεται.</li><li>Επιλέξτε σελίδα και προσθέστε έτοιμη ενότητα, όπως φόρμα κράτησης, παρουσίαση στόλου ή FAQ.</li><li>Επιλέξτε ενότητα στην προεπισκόπηση ή στη λίστα. Ρυθμίστε παραλλαγή, αποστάσεις, στοίχιση και ορατότητα ανά συσκευή.</li><li>Ελέγξτε την πλοήγηση κεφαλίδας και υποσέλιδου και δοκιμάστε τους συνδέσμους.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Προσχέδιο πολλαπλών σελίδων με λειτουργική πλοήγηση. Η δομή αναφοράς υποστηρίζει <code>/</code>, <code>/transfers</code>, <code>/fleet</code>, <code>/tours</code> και <code>/contact</code>, καθώς και νέες σελίδες.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν απορριφθεί διαδρομή, ελέγξτε για διπλότυπα ή μη ασφαλή slugs. Μην παρακάμπτετε την επικύρωση. Η απόκρυψη ενότητας ανά συσκευή δεν διαγράφει το περιεχόμενό της. Δείτε την <a href="./responsive-preview.html">προεπισκόπηση</a>.</p>',10)])])}const u=a(i,[["render",l]]);export{_ as __pageData,u as default};
